import math


def _number(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(name + " must be numeric")
    if not math.isfinite(value) or value < 0:
        raise ValueError(name + " must be finite and non-negative")
    return float(value)


def _matrix(value, name):
    if isinstance(value, (str, bytes)):
        raise TypeError(name + " must be a matrix")
    try:
        rows = list(value)
    except TypeError as exc:
        raise TypeError(name + " must be a matrix") from exc
    converted = []
    width = None
    for row in rows:
        if isinstance(row, (str, bytes)):
            raise TypeError(name + " rows must be sequences")
        try:
            cells = list(row)
        except TypeError as exc:
            raise TypeError(name + " rows must be sequences") from exc
        if width is None:
            width = len(cells)
        elif len(cells) != width:
            raise ValueError(name + " must be rectangular")
        converted.append([_number(cell, name + " cell") for cell in cells])
    return converted


def raise_cover_floor(signal, cover, floor_ratio):
    ratio = _number(floor_ratio, "floor_ratio")
    signal_rows = _matrix(signal, "signal")
    cover_rows = _matrix(cover, "cover")
    signal_shape = (len(signal_rows), len(signal_rows[0]) if signal_rows else 0)
    cover_shape = (len(cover_rows), len(cover_rows[0]) if cover_rows else 0)
    if signal_shape != cover_shape:
        raise ValueError("matrix shapes must match")

    combined = []
    supplements = []
    for signal_row, cover_row in zip(signal_rows, cover_rows):
        combined_row = []
        supplement_row = []
        for signal_cell, cover_cell in zip(signal_row, cover_row):
            extra = max(0.0, ratio * signal_cell - cover_cell)
            supplement_row.append(extra)
            combined_row.append(signal_cell + extra)
        combined.append(combined_row)
        supplements.append(supplement_row)
    return combined, supplements

